import re
B='/home/claude/customer-support-prd/prd/03 - PRD Sections/'
NAME='«[نام و نام خانوادگی] از پشتیبانی فروشگاه به گفت‌وگو پیوست»'
def rw(p,f):
    s=open(B+p,encoding='utf-8').read(); t=f(s); assert t!=s,p; open(B+p,'w',encoding='utf-8').write(t)
def R(s,a,b,n=1):
    assert s.count(a)>=n, a[:70]; return s.replace(a,b)
def ep07(s):
    s=R(s,'version: 1.2\n','version: 1.3\n'); s=R(s,'last_updated: 2026-11-12','last_updated: 2026-11-20')
    s=re.sub(r'(change_note: ".*?)"\n', lambda m: m.group(1)+' · 1.3 — CH-52: نام و نام خانوادگی پشتیبان پس از پیوستن به مشتری نشان داده می‌شود (DEC-303؛ جایگزین بخش نام در DEC-94)"\n', s, count=1)
    s=R(s,'| ‏اطلاع مشتری | ‏پیام سیستمی «پشتیبان فروشگاه به گفت‌وگو پیوست» | DEC-94 |','| ‏اطلاع مشتری | ‏پیام سیستمی '+NAME+' | DEC-94؛ **DEC-303** |')
    s=R(s,'| ‏نام ادمین برای مشتری | ‏به مشتری نشان داده نمی‌شود؛ فقط «پشتیبان فروشگاه» | DEC-94 |','| ‏نام ادمین برای مشتری | ‏پس از پیوستن، نام و نام خانوادگی ادمینی که گفت‌وگو را تحویل گرفته در پیام پیوستن، زیر پیام‌هایش و در نوار وضعیت صفحه گفت‌وگو نشان داده می‌شود؛ جای دیگری نام ادمین به مشتری نشان داده نمی‌شود | ‏**DEC-303** (جایگزین بخش نام DEC-94) |')
    s=R(s,'| ‏اطلاع مشتری | ‏«پشتیبان فروشگاه به گفت‌وگو پیوست.» |','| ‏اطلاع مشتری | ‏«[نام و نام خانوادگی] از پشتیبانی فروشگاه به گفت‌وگو پیوست.» |')
    s=R(s,'| ‏اطلاع مشتری | ‏فقط «پشتیبان فروشگاه به گفت‌وگو پیوست»؛ پیام «درخواست ثبت شد» به مشتری نشان داده نمی‌شود | ‏DEC-94؛ DEC-267 |','| ‏اطلاع مشتری | ‏فقط پیام پیوستن پشتیبان با نام او ('+NAME+')؛ پیام «درخواست ثبت شد» به مشتری نشان داده نمی‌شود | ‏DEC-94؛ DEC-267؛ DEC-303 |')
    s=R(s,'| ‏فقط پیام «پشتیبان فروشگاه به گفت‌وگو پیوست» آمده است، نه «درخواست ثبت شد» | ‏DEC-94؛ DEC-267','| ‏فقط پیام پیوستن پشتیبان با نام او آمده است، نه «درخواست ثبت شد» | ‏DEC-94؛ DEC-267؛ DEC-303')
    s=R(s,'| ‏نمایش برای مشتری | ‏با برچسب «پشتیبان فروشگاه»، جدا از پیام‌های دستیار | ‏DEC-94؛ قاعده ۱۰ متن رابط (04-00) |','| ‏نمایش برای مشتری | ‏با برچسب «[نام و نام خانوادگی] · پشتیبان فروشگاه»، جدا از پیام‌های دستیار | ‏DEC-303؛ قاعده ۱۰ متن رابط (04-00) |')
    s=R(s,'| ‏برچسب پیام برای مشتری | ‏«پشتیبان فروشگاه» |','| ‏برچسب پیام برای مشتری | ‏«[نام و نام خانوادگی] · پشتیبان فروشگاه» |')
    s=R(s,'| ‏مشتری پاسخ را با برچسب «پشتیبان فروشگاه» در همان صفحه می‌بیند | ‏FR-08 |','| ‏مشتری پاسخ را با نام الف و برچسب «پشتیبان فروشگاه» در همان صفحه می‌بیند | ‏FR-08؛ DEC-303 |')
    s=R(s,'| ‏DEC-94 | ‏اطلاع مشتری از تحویل و نام ادمین | ‏پیام «پشتیبان فروشگاه به گفت‌وگو پیوست»؛ نام ادمین به مشتری نشان داده نمی‌شود |','| ‏DEC-94 | ‏اطلاع مشتری از تحویل و نام ادمین | ‏پیام «پشتیبان فروشگاه به گفت‌وگو پیوست»؛ نام ادمین به مشتری نشان داده نمی‌شود — **بخش نام جایگزین‌شده با DEC-303** |\n| ‏DEC-303 | ‏نام پشتیبان برای مشتری | ‏پس از پیوستن، نام و نام خانوادگی ادمینی که گفت‌وگو را تحویل گرفته در پیام پیوستن، زیر پیام‌هایش و در نوار وضعیت نمایش داده می‌شود (CH-52) |')
    s=re.sub(r'(\| ‏1\.2 \| ‏2026-11-12 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏1.3 | ‏2026-11-20 | ‏نام و نام خانوادگی پشتیبان پس از پیوستن: اطلاع مشتری US-07-01 و US-07-02، نمایش و برچسب پیام US-07-03، AC-07-02-6، AC-07-03-1، جدول تصمیم‌ها (DEC-303) | ‏CH-52؛ DEC-303 |\n', s, count=1)
    return s
def dd(s):
    s=R(s,'version: 1.2\n','version: 1.3\n'); s=R(s,'last_updated: 2026-11-12','last_updated: 2026-11-20')
    s=re.sub(r'(change_note: ".*?)"\n', lambda m: m.group(1)+' · 1.3 — CH-52: فرستنده انسانی با نام و نام خانوادگی برای مشتری (DEC-303)"\n', s, count=1)
    s=R(s,'| ‏فرستنده انسانی | ‏شناسه ادمین؛ به مشتری فقط «پشتیبان فروشگاه» نمایش داده می‌شود | ‏DEC-94 |','| ‏فرستنده انسانی | ‏شناسه ادمین؛ به مشتری نام و نام خانوادگی او با برچسب «پشتیبان فروشگاه» نمایش داده می‌شود | ‏DEC-303 (جایگزین بخش نام DEC-94) |')
    s=re.sub(r'(\| ‏1\.2 \| ‏2026-11-12 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏1.3 | ‏2026-11-20 | ‏DS-05 فیلد «فرستنده انسانی»: نام و نام خانوادگی ادمین برای مشتری (DEC-303) | ‏CH-52 |\n', s, count=1)
    return s
def gl(s):
    s=R(s,'version: 1.3\n','version: 1.4\n'); s=R(s,'last_updated: 2026-11-12','last_updated: 2026-11-20')
    s=re.sub(r'(change_note: ".*?)"\n', lambda m: m.group(1)+' · 1.4 — CH-52: مدخل «پشتیبان فروشگاه» (DEC-303)"\n', s, count=1)
    s=R(s,'| ‏پشتیبان فروشگاه | ‏Store support | ‏نامی که مشتری برای ادمین می‌بیند؛ نام خود ادمین نشان داده نمی‌شود | ‏= ادمین پشتیبانی | ‏DEC-94 |','| ‏پشتیبان فروشگاه | ‏Store support | ‏برچسبی که مشتری برای ادمین می‌بیند؛ پس از پیوستن، نام و نام خانوادگی ادمینی که گفت‌وگو را تحویل گرفته کنار آن می‌آید | ‏= ادمین پشتیبانی | ‏DEC-94؛ DEC-303 |')
    s=re.sub(r'(\| ‏1\.3 \| ‏2026-11-12 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏1.4 | ‏2026-11-20 | ‏**CH-52 (DEC-303):** مدخل «پشتیبان فروشگاه» — نام و نام خانوادگی ادمین پس از پیوستن. هیچ نام مرجع دیگری تغییر نکرد |\n', s, count=1)
    return s
rw('PRD-04-EP07 - Human Control.md',ep07); rw('PRD-04-DD - Data Dictionary.md',dd); rw('PRD-15 - Glossary.md',gl)
